from lib import *
S = SS('m33')
steps = [
    step("哈希索引的 key 是 { k: 'hashed' },存的是值的 64 位哈希而不是值本身。convertShardKeyToHashed 能算出同样的哈希:1 → 5902408780260971510,2 → 848411777775835583,3 → -1529429926180645992,4 → 2433984061343616404,5 → 4470791281878691347;字符串 user1 → 801843209332933044,user2 → -4095265838481657615——相邻的值哈希后差很远。", t=tl(S(1)), mark=lidx(S(1), '1 → 5902408780260971510', '2 → 848411777775835583', 'user1 →'), done=lidx(S(1), "key: { k: 'hashed' }", "key: { u: 'hashed' }"), kv=KV([['索引键', '值的 64 位哈希'], ['1 → 5902…', '2 → 848…:相邻值的哈希毫无关系']], ['索引键'])),
    step("等值查询走哈希索引:find({k: 12345}).hint(\"k_hashed\") 是 FETCH > IXSCAN(k_hashed),检查 1 个键、1 个文档;indexBounds 是单点 [7147702579911805439, 7147702579911805439];$in: [1, 2, 3] 是三个单点区间(-1529429926180645992、848411777775835583、5902408780260971510)。", t=tl(S(2)), mark=lidx(S(2), '7147702579911805439', '-1529429926180645992'), done=lidx(S(2), 'keysExamined: 1', 'docsExamined: 1'), kv=KV([['等值', '一个哈希点'], ['$in', '多个哈希点'], ['检查量', '1 个键']], ['等值'])),
    step("范围查询用不了哈希索引:find({k: {$gte: 1000, $lt: 1100}}) 强制 hint k_hashed 要扫整个索引(检查 200,000 个键和文档,142 ms),只返回 100 个;hint 普通索引 k_range 只检查 100 个(2 ms);删掉普通索引后优化器选 COLLSCAN(30 ms);sort({k: 1}) 用哈希索引是 SORT > FETCH > IXSCAN,仍要读 200,000 个文档(141 ms)。", t=tl(S(3)), mark=lidx(S(3), 'keysExamined: 200000', 'COLLSCAN', 'SORT > FETCH'), done=lidx(S(3), 'IXSCAN(k_range)', 'keysExamined: 100'), b=bars([['普通索引 k_range', 100, '100 个键 / 2 ms'], ['COLLSCAN', 200000, '200,000 个文档 / 30 ms'], ['哈希索引范围', 200000, '200,000 个键 / 142 ms']], 200000, mark=[2], done=[0, 1]), kv=KV([['范围', '哈希索引没法用,被迫扫整个索引'], ['排序', '也不行,要 SORT'], ['结论', '只做等值']], ['结论'])),
    step("哈希索引的限制:unique 报 Currently hashed indexes cannot guarantee uniqueness. Use a regular index.;数组字段报 hashed indexes do not currently support array values. Found array at path: k;两个哈希字段报 A maximum of one index field is allowed to be hashed but found 2;一个普通字段加一个哈希字段的复合索引 {a: 1, b: \"hashed\"} 可以建(ab)。", t=tl(S(4)), mark=lidx(S(4), 'cannot guarantee uniqueness', 'do not currently support array', 'A maximum of one index field'), done=lidx(S(4), '  ab'), kv=KV([['unique', '不支持'], ['数组', '不支持'], ['哈希字段个数', '复合索引里最多 1 个']], ['unique'])),
    step("浮点数会先被截断成整数再哈希:2.1、2.3、2.9 的哈希都是 848411777775835583(和整数 2 一样),3 才是 -1529429926180645992。哈希索引上查 x = 2.3 检查了 3 个键、3 个文档,只返回 1 个文档(_id 2),结果仍然正确,但多读了 2 个。", t=tl(S(5)), mark=lidx(S(5), 'keysExamined: 3', '[ 2 ]'), done=lidx(S(5), '2.1 → 848411777775835583', '3 → -1529429926180645992'), kv=KV([['2.1 / 2.3 / 2.9', '哈希相同(都按 2 哈希)'], ['结果', '仍然正确'], ['代价', '多检查键和文档']], ['2.1 / 2.3 / 2.9'])),
    step("哈希的分布:$toHashedIndexKey 在聚合里算出 k=0、1、2 的哈希(与 convertShardKeyToHashed 一致:1 → 5902408780260971510);连续整数 0..7 的哈希分别是 +4.9e18、+5.9e18、+0.8e18、-1.5e18、+2.4e18、+4.5e18、-6.5e18、+9.2e18;4000 个连续整数的哈希落在 8 等分的 64 位空间里的个数是 [482, 506, 505, 488, 506, 507, 528, 478],基本均匀(期望每份 500)。", t=tl(S(6)), mark=lidx(S(6), '[482, 506, 505, 488, 506, 507, 528, 478]'), done=lidx(S(6), '前 8 个连续整数', '$toHashedIndexKey'), b=bars([['空间 1/8', 482, '482'], ['空间 2/8', 506, '506'], ['空间 3/8', 505, '505'], ['空间 4/8', 488, '488'], ['空间 5/8', 506, '506'], ['空间 6/8', 507, '507'], ['空间 7/8', 528, '528'], ['空间 8/8', 478, '478']], 528, mark=[6], done=[0, 1, 2, 3, 4, 5, 7]), kv=KV([['4000 个连续整数', '均匀分散到 8 份(478~528)'], ['用途', '分片键用哈希避免写入热点']], ['4000 个连续整数'])),
]
A = mkartm('m33', 33, 'MongoDB,哈希索引,hashed,分片,等值查询,真实验证,动画演示',
    '实测哈希索引:存值的 64 位哈希,相邻值哈希后差很远;只能做等值,范围查询要扫整个索引(200,000 个键,142 ms 对普通索引的 2 ms),排序也不行;不支持 unique、数组,复合索引最多一个哈希字段;浮点数会截断成整数再哈希;连续整数哈希后均匀分散。',
    '哈希索引能做什么、不能做什么?这篇从索引键的实际哈希值看起,验证等值、范围、排序、限制、浮点截断和分布。',
    [('100 对 200,000', '范围查询在普通索引与哈希索引上检查的键数'), ('2.1 = 2.3 = 2.9', '哈希索引对这三个浮点数算出同一个哈希(它们都先被截断成 2)'), ('478~528', '4000 个连续整数哈希后落在 8 等分空间里的各份个数(期望 500)')],
    [('索引存什么', '<p>哈希索引存的是字段值的 64 位哈希。相邻的整数哈希后毫无关系,所以只支持等值。</p>'),
     ('等值查询', '<p>等值是一个单点区间,<code>$in</code> 是多个单点区间,检查 1 个键。</p>'),
     ('范围与排序', '<p>范围查询要扫整个哈希索引(200,000 个键、142 ms),普通索引只要检查 100 个键;排序也不能利用,需要 SORT 阶段。</p>'),
     ('限制', '<p>不支持 unique、不支持数组字段,复合索引里最多一个哈希字段。</p>'),
     ('浮点数', '<p>浮点数先截断成 64 位整数再哈希,所以 2.1、2.3、2.9 的哈希相同。查询结果仍然正确,但会多检查键和文档。</p>'),
     ('分布', '<p>连续整数哈希后均匀分散到整个 64 位空间,这是它适合做分片键、避免写入热点的原因。</p>')],
    steps,
    [ENV_M + '。哈希值来自 convertShardKeyToHashed 与聚合的 $toHashedIndexKey;20 万个文档,k 是 0~199999 的整数',
     '没有验证:哈希索引作为分片键时的 chunk 分布(后面单独一篇);字符串、ObjectId、日期等类型的哈希是否也均匀;哈希碰撞的实际概率;复合哈希索引的前缀字段查询;哈希索引占用的磁盘空间对比普通索引'],
    '哈希索引')
